# The form deliberately accepts only the canonical origin. Send www visitors
# there before its scripts run, retaining service, confirmation and status links.
www_redirect = '<script id="atd-canonical-host">if(location.hostname==="www.atdnorthlondon.co.uk"){location.replace("https://atdnorthlondon.co.uk"+location.pathname+location.search+location.hash);}</script>'
for page in D.rglob('*.html'):
    content = page.read_text()
    if 'id="atd-canonical-host"' not in content:
        page.write_text(content.replace('<head>', '<head>'+www_redirect, 1))
